//! 🚦️ Exact Chart Record envelopes and same-caller controlled native ownership.
use crate::ChartSnapshot;
use protocol as store;
use semio_framework_dsl_record::{BorrowedFieldSpec as F,BorrowedRecordSpec as R,BorrowedShape as H,RecordLayout};
use semio_framework_value::{FromValue,ValueError,ValueRefusalKind as K,native_encoding::NativeEncodeProgress};
use store::os_store::serialization::{SnapshotReceivingOutcome,SnapshotReceivingOutput};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl,SqliteSnapshotPhase};
use semio_framework_diagnostic::{TextError,TextSpan};
static FIELD:[F;1]=[F::new(0,"chart",H::Value)];
fn spec()->R{R{keyword:None,layout:RecordLayout::Inline,fields:&FIELD}}
pub(super) fn decode(payload:&store::io_schema::IoPayload,control:&mut SqliteSnapshotControl<'_>,native_owner:&mut store::NativeSnapshotDecodeOwner<'_,'_>,output:&mut Option<SnapshotReceivingOutput<ChartSnapshot>>)->SnapshotReceivingOutcome {store::decode_sqlite_snapshot_record_native(payload,"print.chart",ChartSnapshot::__dsl_spec_producer(),&mut |record,snapshot_output,native|{let constructed:Result<_,ValueError>=ChartSnapshot::__dsl_from_record_controlled(record,native);*snapshot_output=Some(constructed?);Ok(())},control,native_owner,output)}
pub(super) fn preflight(snapshot:&ChartSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{let component=match encoding{SnapshotEncoding::Binary=>store::semio_format::Component::Pack,SnapshotEncoding::Text=>store::semio_format::Component::Dsl};let maximum=control.limits().max_file_bytes.checked_sub(store::semio_format::declared_envelope_prefix_len("print.chart",component,1)?).ok_or_else(||ValueError::new(K::OwnershipLimit,"Chart file ceiling cannot contain its declared envelope"))?;
 control.allocation_stage(SqliteSnapshotPhase::EncodeNative,|remaining,checkpoint,allocation|{let mut progress=|event:NativeEncodeProgress|checkpoint(event.completed,event.total);let mut native=allocation.encode(remaining,&mut progress);let result=match encoding{SnapshotEncoding::Text=>semio_framework_dsl_record::measure_print_borrowed(snapshot,&spec(),maximum,&mut native),SnapshotEncoding::Binary=>pack::record::measure_document_borrowed(snapshot,&spec(),&Default::default(),&mut native)}.and_then(|length|if length>maximum{Err(ValueError::new(K::OwnershipLimit,"Chart native output exceeds file byte ceiling"))}else{Ok(())});(result,native.owned_bytes())})?
}
pub(super) fn encode(snapshot:&ChartSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>,native_owner:&mut store::NativeSnapshotEncodeOwner<'_,'_>,output:&mut Option<SnapshotReceivingOutput<store::io_schema::IoPayload>>)->SnapshotReceivingOutcome {if let Err(error)=preflight(snapshot,encoding,control){return semio_framework_value::RetainedWorkOutcome{result:Err(store::sqlite_snapshot::SqliteStageFailure::NotStarted(error)),work:0}}store::encode_sqlite_snapshot_record_native(encoding,"print.chart",ChartSnapshot::__dsl_spec_producer(),&mut |native|snapshot.__dsl_to_record_controlled(native),control,native_owner,output)}
